static int ap_check_grouped_image(FILE *input) {
    unsigned char actual[256];
    for(size_t i=0;i<sizeof(ap_group_image_slices)/sizeof(ap_group_image_slices[0]);i++) {
        const struct ap_copy_image_slice *s=&ap_group_image_slices[i];
        if(fseek(input,s->offset,SEEK_SET))return -1;
        for(size_t at=0;at<s->size;) {
            size_t n=s->size-at;if(n>sizeof(actual))n=sizeof(actual);
            if(fread(actual,1,n,input)!=n) {if(!ferror(input))errno=ENODATA;return -1;}
            if(memcmp(actual,s->bytes+at,n)) {errno=ESTALE;return -1;}
            at+=n;
        }
    }
    return 0;
}
#include "executable-source-image.h"
static int ap_require_grouped_target(void) {
    if(ap_require_retirement_target())return -1;
    FILE *input=fopen(AP_COPY_KERNEL_IMAGE,"re");if(!input)return -1;
    int rc=ap_check_grouped_image(input);
    if(!rc)rc=ap_check_executable_image(input);
    int saved=errno;
    if(fclose(input) && !rc)return -1;
    errno=saved;return rc;
}
